"""Working demo for this book record: full reader + HTML exporter.
Run:  python3 book_demo.py              (prints the whole book)
      python3 book_demo.py 3            (prints chapter 3 only)
      python3 book_demo.py search WORD  (finds WORD across chapters)
      python3 book_demo.py html         (writes book.html)
"""
import json, sys, html as _h

BOOK = {'title': 'A Season for Love', 'author': 'Signature original', 'genre': 'Workplace Romance', 'chapters': [{'n': 1, 'title': 'Homecoming', 'text': "He was there — the boy from that summer, grown into a man with the same laugh. Time folded. Claire Bennett's heart, so carefully guarded, did something reckless: it hoped.\n\nher sister Lily met her at the station with a hug that smelled of Maple Hollow: salt, wildflowers, fresh bread. 'You look like you need pie,' her sister Lily said, which was her sister Lily's diagnosis for everything, and usually right.\n\nClaire Bennett hadn't meant to come back to Maple Hollow. The city had been fine — fine in the way a waiting room is fine. But the letter about the old house, and a mixtape tucked inside it, had pulled her home like a tide."}, {'n': 2, 'title': 'The Thing Remembered', 'text': "He found her at the bookshop, reaching for the same novel. Their hands touched. The whole shop seemed to hold its breath. 'You came back,' he said, and it wasn't a question, it was a prayer answered.\n\nThey talked until the shop closed, until the streetlights came on in Maple Hollow. Seventeen years of almosts poured out: the almost-letters, the almost-calls, the life they'd almost shared.\n\nher sister Lily listened to the whole story over coffee and said what best friends say: 'You have to talk to him.' Claire Bennett said she couldn't. her sister Lily said she must. They were both right."}, {'n': 3, 'title': 'Complications', 'text': "Her grandmother Rose's voice came back to her: 'The heart knows first, baby. The head just takes minutes.' Claire Bennett stopped running. She turned around and went to find him.\n\nHe — the bookshop man, the summer boy — went quiet. Not angry, just hurt, in the way of someone who's waited seventeen years and can wait no longer. Claire Bennett felt the old panic rise: run, before it breaks.\n\na mixtape sat on her dresser, accusing and comforting by turns. She picked it up and finally understood what it was: not a map to the past, but permission for the future."}, {'n': 4, 'title': 'The Choice', 'text': 'He laughed through tears, the same laugh, and the sunset did its thing, and Maple Hollow held its breath again. This time nobody interrupted. This time they stayed.\n\nher overbearing mother left town with the gift wrap and the almosts. Claire Bennett felt nothing but pity — and then not even that, because her arms were full of present tense.\n\na mixtape got a place of honor on the mantel — not as a relic, but as a reminder: that love lost can be love found, that the heart knows first, and that home was never a town at all.'}, {'n': 5, 'title': 'The Promise', 'text': "He proposed with a mixtape — fitting, her sister Lily said, since it started everything. Claire Bennett said yes before he finished asking, because seventeen years is long enough to wait for a sentence.\n\nThe wedding was in Maple Hollow, in the season of wildflowers. Her grandmother Rose's quilt was on the bed. her sister Lily gave a speech that made everyone cry laughing.\n\nthe heart knows first — Claire Bennett wrote it in the new journal, the one for the next seventeen years. In Maple Hollow, under the stars, with love: the whole story, and only just beginning."}, {'n': 6, 'title': 'Epilogue in Wildflowers', 'text': "the heart knows first. In Maple Hollow, in the wildflowers, in the salt air, in every sunset: the whole story, still beginning, never ending.\n\nAnd when the children ask about a mixtape, Claire Bennett tells them: it was a map. Not to a place — to a person. To the bravest thing she ever did, which was to come home.\n\nYears later, a mixtape sits on the mantel still, a little faded, entirely cherished. The house is full of noise: children, dogs, her sister Lily's children, the whole beautiful chaos of a life chosen."}]}

def word_count():
    return sum(len(c["text"].split()) for c in BOOK["chapters"])

def print_book(ch=None):
    print("=" * 64)
    print(BOOK["title"].upper(), "\nby", BOOK["author"], "-", BOOK["genre"])
    print("=" * 64)
    for c in BOOK["chapters"]:
        if ch and c["n"] != ch:
            continue
        print("\n\nCHAPTER %d: %s\n%s" % (c["n"], c["title"], "-" * 40))
        print(c["text"])
    print("\n[%d words, %d chapters — complete]" % (word_count(), len(BOOK["chapters"])))

def search(word):
    w = word.lower()
    for c in BOOK["chapters"]:
        for i, para in enumerate(c["text"].split("\n\n")):
            if w in para.lower():
                print("[ch %d, para %d] %s..." % (c["n"], i + 1, para[:160].replace("\n", " ")))

def write_html(path="book.html"):
    parts = ["<html><head><meta charset='utf-8'><title>%s</title></head><body>" % _h.escape(BOOK["title"])]
    parts.append("<h1>%s</h1><p><i>by %s — %s</i></p>" % (_h.escape(BOOK["title"]), _h.escape(BOOK["author"]), _h.escape(BOOK["genre"])))
    for c in BOOK["chapters"]:
        parts.append("<h2>Chapter %d: %s</h2>" % (c["n"], _h.escape(c["title"])))
        for para in c["text"].split("\n\n"):
            parts.append("<p>%s</p>" % _h.escape(para))
    parts.append("</body></html>")
    open(path, "w").write("\n".join(parts))
    print("wrote", path)

if __name__ == "__main__":
    a = sys.argv[1:]
    if a and a[0] == "html":
        write_html()
    elif len(a) >= 2 and a[0] == "search":
        search(a[1])
    elif a and a[0].isdigit():
        print_book(int(a[0]))
    else:
        print_book()

